1	//! Издержки и проскальзывание по Decision 15 (план, §5.3).
2	//!
3	//! Вход — мейкер у своей стороны спреда без улучшения (тип ордера —
4	//! Decision 19); выход — тейкер с издержкой в один тик против позиции плюс
5	//! половина наблюдённого спреда в момент выхода. Круг комиссий —
6	//! по ногам: мейкер 0.014 % / тейкер 0.035 % минус 10 % возврата (В-63, условия счёта
7	//! владельца 2026-09-18; прежнее H4 — публичный non-VIP 0.02 % / 0.055 %).
8	//!
9	//! Формула на наблюдение: `net = m − (7.5 + slippage)`, где `m` — подписанный
10	//! markout по Decision 14 (потребитель: `markout::markout_bps`), а slippage
11	//! считается на каждом наблюдении отдельно из его же спреда выхода и его же
12	//! базовой середины. Валового порога-константы нет (H6): тик на тонком
13	//! инструменте честно весит больше, потому что знаменатель — цена.
14	//!
15	//! Целые до последнего, как в книге (A7): тики — `i64`, середина держится
16	//! удвоенной суммой `bid + ask` (ровно держит половину тика без деления),
17	//! вещественное число появляется один раз — при делении в формуле bps.
18	//!
19	//! Вывод slippage: цена издержки = 1 тик + spread_exit / 2 тика, то есть
20	//! `(spread + 2) / 2` тиков; середина базы = `mid2x / 2` тиков, где
21	//! `mid2x = bid_base + ask_base`. Масштаб тика сокращается:
22	//! `slippage_bps = (spread + 2) / mid2x * 10^4`. Числитель — целый (`i128`),
23	//! деление одно.
24	//!
25	//! Знаменатель — базовая середина, тот же, что у `m`: net вычитается
26	//! из markout без смены базы. Спред — наблюдённый в момент выхода
27	//! (`ask_exit − bid_exit` в тиках, потребитель: `book`).
28	//!
29	//! Вердикт «эдж после издержек положителен» больше не выносится здесь
30	//! (таск 17 снял `VerdictCell`/`G3Verdict`/`select_verdict_cell`/`decide_g3*`
31	//! — построены под отменённую ячеечную модель C1/C2 §5.2, `interfaces.md`
32	//! «Что построено под отменённый дизайн»; ни один вызывающий не читал их —
33	//! живой вердикт на очереди даёт `backtest::G4Verdict`/`decide_g4`).
34	//! Зелёный порог H6 (`GREEN_NET_BPS`, средний net ≥ 3 bps) остаётся здесь
35	//! просто числом: `shortlist` сравнивает с ним готовый `net_fill`.
36	//!
37	//! Модуль не хранит состояния и не выделяет память.
38	
39	use crate::lob::cells::joint_product_interval;
40	use crate::lob::levels::LevelRecord;
41	use crate::lob::markout::{base_before, markout_bps, sample_asof, MidSample};
42	use crate::stats::{count_f64, count_f64_u64};
43	use std::collections::BTreeMap;
44	
45	/// Комиссия мейкера, bps: 0.014 % — условия счёта владельца (скриншот
46	/// account.tiger.com, 2026-09-18, В-63). Прежнее H4 — публичный non-VIP 0.02 %.
47	pub const MAKER_FEE_BPS: f64 = 1.4;
48	
49	/// Комиссия тейкера, bps: 0.035 % (там же). Прежнее H4 — 0.055 %.
50	pub const TAKER_FEE_BPS: f64 = 3.5;
51	
52	/// Возврат комиссий владельцу: 10 % от уплаченного (там же, «вы получаете 10 %
53	/// вознаграждения от торговых комиссий»). Применяется к каждой ноге.
54	pub const FEE_REBATE_SHARE: f64 = 0.10;
55	
56	/// Эффективная комиссия одной ноги после возврата, bps: мейкер 1.26, тейкер 3.15.
57	pub fn leg_fee_bps(taker: bool) -> f64 {
58	    (if taker { TAKER_FEE_BPS } else { MAKER_FEE_BPS }) * (1.0 - FEE_REBATE_SHARE)
59	}
60	
61	/// Круг мейкер-тейкер после возврата, bps (Decision 19 → В-63): одно число
62	/// для markout-метрик, у которых ног нет (G0, G3, дашборд, отбор, пол тейка);
63	/// круг **сделки** считается по ногам — `backtest::roundtrip_net_bps`.
64	pub const ROUNDTRIP_FEES_BPS: f64 = (MAKER_FEE_BPS + TAKER_FEE_BPS) * (1.0 - FEE_REBATE_SHARE);
65	
66	/// Зелёный порог H6, bps: средний net ≥ 3 сверх полных издержек.
67	/// Только читается; вердикт G3 его не использует.
68	pub const GREEN_NET_BPS: f64 = 3.0;
69	
70	/// Одно наблюдение для колонки «после издержек»: markout и его же издержки.
71	/// `spread_ticks_exit = ask_exit − bid_exit` в тиках; `mid2x_base` — удвоенная
72	/// середина базы (`bid + ask` в тиках, см. `markout::mid_double_tick`).
73	#[derive(Debug, Clone, Copy, PartialEq)]
74	pub struct Observation {
75	    /// Подписанный markout `m` в bps (Decision 14).
76	    pub m_bps: f64,
77	    /// Наблюдённый спред в момент выхода, в тиках.
78	    pub spread_ticks_exit: i64,
79	    /// Удвоенная середина базы в тиках.
80	    pub mid2x_base: i64,
81	}
82	
83	/// Наблюдение `net` для уровня на горизонте `horizon_ms`: markout от базы
84	/// Decision 11 (последний срез строго до смерти) до среза «как есть» на
85	/// `base + horizon` и спред того же среза выхода. Одна конструкция на всех
86	/// читателей (`lob pilot`, `lob dashboard`; до таска 33 каждый нёс свою
87	/// копию петли `base_before` → срез выхода → `Observation`). `None` — нет
88	/// базы, нет среза на горизонте или середина не положительна.
89	pub fn observation_at(
90	    level: &LevelRecord,
91	    mids: &[MidSample],
92	    horizon_ms: i64,
93	) -> Option<Observation> {
94	    let (base_ts, base2x) = base_before(mids, level.death_ms)?;
95	    let exit = sample_asof(mids, base_ts, horizon_ms)?;
96	    let m_bps = markout_bps(
97	        level.side,
98	        base2x,
99	        crate::lob::markout::mid_double_tick(exit.bid_tick, exit.ask_tick),
100	    )?;
101	    Some(Observation {
102	        m_bps,
103	        spread_ticks_exit: exit.ask_tick - exit.bid_tick,
104	        mid2x_base: base2x,
105	    })
106	}
107	
108	/// Проскальзывание Decision 15 в bps: `(spread + 2) / mid2x * 10^4`.
109	/// `None` при неположительной базе, отрицательном спреде или переполнении
110	/// входа за пределы `i128` (практически недостижимо, проверка — страховка).
111	/// Целые до деления: числитель складывается в целых, деление одно.
112	pub fn slippage_bps(spread_ticks_exit: i64, mid2x_base: i64) -> Option<f64> {
113	    if mid2x_base <= 0 || spread_ticks_exit < 0 {
114	        return None;
115	    }
116	    let num = (i128::from(spread_ticks_exit) + 2) * 10_000;
117	    // Числитель — тики единиц–десятков × 10⁴ (~1e5–1e6), знаменатель —
118	    // удвоенная середина в e9 (~1e13–1e14): оба точны в f64 (< 2^53).
119	    #[allow(clippy::cast_precision_loss)]
120	    let (num_f, den_f) = (num as f64, mid2x_base as f64);
121	    Some(num_f / den_f)
122	}
123	
124	/// Полные издержки круга в bps: 7.5 комиссий плюс проскальзывание.
125	/// `None` — проскальзывание не посчиталось (см. `slippage_bps`).
126	pub fn cost_bps(spread_ticks_exit: i64, mid2x_base: i64) -> Option<f64> {
127	    slippage_bps(spread_ticks_exit, mid2x_base).map(|s| ROUNDTRIP_FEES_BPS + s)
128	}
129	
130	/// Чистый результат наблюдения в bps: `m − cost`. `None` при неконечном `m`
131	/// или при `None` издержек: отсутствие данных не есть нулевая издержка.
132	pub fn net_bps(m_bps: f64, spread_ticks_exit: i64, mid2x_base: i64) -> Option<f64> {
133	    if !m_bps.is_finite() {
134	        return None;
135	    }
136	    cost_bps(spread_ticks_exit, mid2x_base).map(|c| m_bps - c)
137	}
138	
139	/// Средний net среза наблюдений — одна колонка «после издержек».
140	/// Считается из понаблюдательных net, а не из средних входов: при разных
141	/// ценах средний вес тика отличается, и константная издержка дала бы другой
142	/// вердикт на тех же данных (H6). `None` — срез пуст или хотя бы одно
143	/// наблюдение не посчиталось: молча выкидывать его значило бы пересчитывать
144	/// выборку задним числом (то же правило, что неконечный markout в 5.2).
145	pub fn mean_net_bps(observations: &[Observation]) -> Option<f64> {
146	    if observations.is_empty() {
147	        return None;
148	    }
149	    let mut sum = 0.0;
150	    for o in observations {
151	        sum += net_bps(o.m_bps, o.spread_ticks_exit, o.mid2x_base)?;
152	    }
153	    Some(sum / count_f64(observations.len()))
154	}
155	
156	// ---------------------------------------------------------------------------
157	// `net_fill` (таск 03, истории 19–22, §6): «вот это и есть окупается».
158	// ---------------------------------------------------------------------------
159	
160	/// Одно наблюдение для `net_fill`: `net` после издержек (см. `net_bps`),
161	/// признак исполнения входа за 2 с (R06) и сутки как целый кластер для
162	/// совместного бутстрапа — тот же смысл кластера, что у
163	/// `stats::wild_cluster_bootstrap_t` (сравнение и группировка по целому,
164	/// не по `f64`, A1).
165	#[derive(Debug, Clone, Copy, PartialEq)]
166	pub struct FillObservation {
167	    /// Сутки UTC как целый кластер.
168	    pub day_cluster: i64,
169	    /// `net` этого наблюдения в bps (после издержек).
170	    pub net_bps: f64,
171	    /// Исполнился ли вход за 2 с (Decision, R06). `false` — не исполнился
172	    /// или позиция уже была открыта; какая из двух причин — не поле этой
173	    /// структуры (см. CONCERNS: колонки причины пропуска — гейт Е/задача 09).
174	    pub filled: bool,
175	}
176	
177	/// Точечный `net_fill` в bps — по наблюдению, буквально `Σ netᵢ·fillᵢ / N`
178	/// (R07): НЕ произведение отдельно посчитанных средних `net` и доли `fill`
179	/// — `fill` коррелирует с исходом (бриф), и подмена суммы произведением
180	/// агрегатов дала бы другое число на тех же данных. `None` — срез пуст или
181	/// хотя бы один `net_bps` не конечен: молча пропускать наблюдение значило
182	/// бы пересчитывать выборку задним числом (то же правило, что в
183	/// `mean_net_bps`).
184	pub fn net_fill_bps(observations: &[FillObservation]) -> Option<f64> {
185	    if observations.is_empty() {
186	        return None;
187	    }
188	    let mut sum = 0.0;
189	    for o in observations {
190	        if !o.net_bps.is_finite() {
191	            return None;
192	        }
193	        let fill_indicator = if o.filled { 1.0 } else { 0.0 };
194	        sum += o.net_bps * fill_indicator;
195	    }
196	    Some(sum / count_f64(observations.len()))
197	}
198	
199	/// Доля исполнений (`fill`), R06: печатается отдельной колонкой всегда, а
200	/// не только в вердикте (см. `format_fill_column`). `None` — срез пуст.
201	pub fn fill_rate(observations: &[FillObservation]) -> Option<f64> {
202	    if observations.is_empty() {
203	        return None;
204	    }
205	    let filled = observations.iter().filter(|o| o.filled).count();
206	    Some(count_f64(filled) / count_f64(observations.len()))
207	}
208	
209	/// Готовая колонка `fill` для CSV/отчёта — R06 требует её печатать всегда,
210	/// а не только внутри вердикта. Проводка в писатель `shortlist`/`commands`
211	/// (task 06/10) — эта функция лишь форматирует уже посчитанное число,
212	/// колонки не изобретает.
213	pub fn format_fill_column(rate: Option<f64>) -> String {
214	    match rate {
215	        Some(v) => format!("{v:.4}"),
216	        None => "none".to_string(),
217	    }
218	}
219	
220	/// Итог совместного интервала `net_fill` (R08/R50): точка (тождественно
221	/// `net_fill_bps` на тех же данных — алгебраическое тождество, не оценка:
222	/// `Σᵢ netᵢ·fillᵢ = Σ_{fillᵢ=1} netᵢ`, значит `mean(net|fill=1)·fill_rate
223	/// = (Σ_{fill=1}netᵢ/n_filled)·(n_filled/N) = Σ netᵢ·fillᵢ/N`) и нижняя
224	/// граница — то, что сравнивается с нулём («окупается», бриф).
225	#[derive(Debug, Clone, Copy, PartialEq)]
226	pub struct NetFillInterval {
227	    /// Исполнившихся входов, суммарно по суткам.
228	    pub n_filled: u64,
229	    /// Всего входов (знаменатель `N`), суммарно по суткам.
230	    pub n_total: u64,
231	    /// Точка: `net_fill`, bps.
232	    pub point_bps: f64,
233	    /// Нижняя граница интервала, bps.
234	    pub lower_bps: f64,
235	    /// Число реплик.
236	    pub replications: u32,
237	    /// Seed реплик.
238	    pub seed: u64,
239	}
240	
241	/// Нижняя граница интервала `net_fill` совместным ресэмплингом пары
242	/// `(net, fill)`: один вес Уэбба на обе серии в одной реплике, произведение
243	/// считается на реплику (R08/R50) — расширение `cells::disjoint_contrast`
244	/// (`cells::joint_product_interval`), а не второй бутстрап. Наблюдения
245	/// группируются по `day_cluster` в `BTreeMap`, как `stats::group_by_cluster`:
246	/// порядок обхода детерминирован и не зависит от порядка входного среза
247	/// (ARCHITECTURE.md A2). Разложение на два ряда — среднее `net` там, где
248	/// `fill = true` (числитель `Σnetᵢ`, знаменатель `n_filled`), и доля `fill`
249	/// (числитель `n_filled` тех же суток, знаменатель `n_total`) — таково, что
250	/// их произведение на наблюдённых данных равно точке `net_fill_bps` (см.
251	/// `NetFillInterval`), а на репликах — совместному ресэмплингу с общим
252	/// весом на сутки, как того требует критерий.
253	///
254	/// `alpha` — односторонний уровень нижнего перцентиля, обязательный
255	/// параметр без умолчания (§9 плана: изобретённое число запрещено; спека
256	/// не называет число для этого гейта, в отличие от `stats::GATE_ALPHA` —
257	/// той альфы гейта G2). `None` — срез пуст, хотя бы один `net_bps` не
258	/// конечен, или исполнений нет вовсе (числитель `mean(net|filled)` не из
259	/// чего считать).
260	#[allow(clippy::cast_precision_loss)]
261	pub fn net_fill_interval(
262	    observations: &[FillObservation],
263	    alpha: f64,
264	    replications: u32,
265	    seed: u64,
266	) -> Option<NetFillInterval> {
267	    if observations.is_empty() || observations.iter().any(|o| !o.net_bps.is_finite()) {
268	        return None;
269	    }
270	    let mut by_day: BTreeMap<i64, (f64, u64, u64)> = BTreeMap::new();
271	    for o in observations {
272	        let entry = by_day.entry(o.day_cluster).or_insert((0.0, 0, 0));
273	        entry.2 = entry.2.saturating_add(1);
274	        if o.filled {
275	            entry.0 += o.net_bps;
276	            entry.1 = entry.1.saturating_add(1);
277	        }
278	    }
279	    let day_sums: Vec<(f64, u64, f64, u64)> = by_day
280	        .values()
281	        .map(|&(sum_net_filled, n_filled, n_total)| {
282	            (sum_net_filled, n_filled, count_f64_u64(n_filled), n_total)
283	        })
284	        .collect();
285	    let jp = joint_product_interval(&day_sums, alpha, replications, seed)?;
286	    Some(NetFillInterval {
287	        n_filled: jp.n_a,
288	        n_total: jp.n_b,
289	        point_bps: jp.point,
290	        lower_bps: jp.lower,
291	        replications: jp.replications,
292	        seed: jp.seed,
293	    })
294	}
